<?php require_once 'conexion.php'; $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$id) die('ID inválido.'); $s=$conn->prepare('SELECT nombre_original,ruta_archivo FROM materiales WHERE id=?'); $s->bind_param('i',$id); $s->execute(); $m=$s->get_result()->fetch_assoc(); if(!$m) die('Material no encontrado.'); $ruta=__DIR__.'/'.$m['ruta_archivo']; if(!is_file($ruta)) die('Archivo no encontrado.'); header('Content-Type: application/octet-stream'); header('Content-Disposition: attachment; filename="'.str_replace('"','',$m['nombre_original']).'"'); header('Content-Length: '.filesize($ruta)); readfile($ruta); exit; ?>
